Edytor.Tekst:
public void Dodatek_Roczny_Param(
    Soneta.Place.WypElementDodatek Element, WypSkladnik Składnik)
{
    CzasDni cd = Element.Pracownik.Czasy.Norma(Składnik.Okres);
    Składnik.Czas = cd.Czas;
    Składnik.Dni = cd.Dni;

    DoubleCy kwotaWpisana = Element.DodHistoria.Podstawa;

    // Okres, za jaki przysługuje dodatek — wskazuje operator w polu "Okres" dodatku
    // (kartoteka pracownika → Etat → Dodatki). Element NIE jest przypisany do konkretnego roku.
    FromTo rocznyOkres = Element.DodHistoria.Okres;

    // Log warunków — widoczny na formularzu elementu, zakładka "Zapis obliczeń"
    Element.ZapisObliczen.Add($"Dodatek roczny za okres {rocznyOkres} - warunki:");

    // Bramka 0) Operator musi wskazać okres — bez niego nie ma czego liczyć
    if (rocznyOkres.From == Date.Empty || rocznyOkres.To == Date.Empty) {
        Element.ZapisObliczen.Add("- BŁĄD: nie wskazano okresu dodatku (pole \"Okres\" w kartotece) — wynik wyzerowany");
        Składnik.Podstawa1 = DoubleCy.Zero;
        Element.ZapisObliczen.Add($"=> wynik: {Składnik.Podstawa1}");
        return;
    }

    // 1) Zatrudnienie przez cały wskazany okres (§3 ust.1b)
    FromTo okresZatr = Element.PracHistoria.Etat.OkresZatrudnienia;
    bool pelnyRok = okresZatr.From <= rocznyOkres.From
        && (okresZatr.To == Date.Empty || okresZatr.To >= rocznyOkres.To);
    Element.ZapisObliczen.Add($"- zatrudnienie przez cały okres {rocznyOkres}: {pelnyRok} (okres zatrudnienia: {okresZatr})");

    // 2) Zatrudnienie trwa na dzień wypłaty (§5 ust.7)
    bool aktywnyNaWyplate = okresZatr.To == Date.Empty || okresZatr.To >= Składnik.Okres.To;
    Element.ZapisObliczen.Add($"- zatrudniony na dzień wypłaty: {aktywnyNaWyplate}");

    // 3) Frekwencja 100% w KAŻDYM miesiącu wskazanego okresu (§2 ust.3-4, §5 ust.5)
    bool frekwencja = true;
    Periods miesiace = Periods.New(rocznyOkres).BreakByMonth();
    foreach (FromTo miesiac in miesiace)
        foreach (Nieobecnosc n in Element.Pracownik.Nieobecnosci[miesiac])
            if (!CzyDozwolonaNieobecnosc(n)) {
                frekwencja = false;
                Element.ZapisObliczen.Add($"  - łamiąca frekwencję: {n.Definicja.Nazwa} ({n.Okres})");
            }
    Element.ZapisObliczen.Add($"- frekwencja 100% w całym okresie: {frekwencja}");

    Składnik.Podstawa1 = (pelnyRok && aktywnyNaWyplate && frekwencja) ? kwotaWpisana : DoubleCy.Zero;

    Element.ZapisObliczen.Add($"- kwota wpisana operatorowi: {kwotaWpisana}");
    Element.ZapisObliczen.Add($"=> wynik: {Składnik.Podstawa1}");
}

public Currency Dodatek_Roczny_Wylicz(
    Soneta.Place.WypElementDodatek Element, WypSkladnik Składnik)
{
    return Składnik.Podstawa1;
}

private bool CzyDozwolonaNieobecnosc(Nieobecnosc n)
{
    // Nazwy zweryfikowane wprost w tabeli DefNieobecnosci na bazie Al.
    // Brak osobnej definicji "odbiór dnia za nadgodziny" (§2 ust.4a.iii) — w tym systemie
    // realizowane jako korekta harmonogramu/grafiku, nie jako rekord Nieobecność, więc
    // naturalnie nie pojawia się w tej pętli i nie łamie frekwencji.
    switch (n.Definicja.Nazwa)
    {
        case "Urlop wypoczynkowy":
            // urlop "na żądanie" WYKLUCZA dozwolenie (§2 ust.4a.i) — pole z API
            return n.Urlop.Przyczyna != PrzyczynaUrlopu.NaŻądanie;

        case "Urlop okolicznościowy":
        case "Urlop opiekuńczy (art 188 kp, dni)":
        case "Urlop opiekuńczy (art 188 kp, godz.)":
        case "Badania lekarskie":
            return true;

        default:
            return false; // każda inna nieobecność łamie frekwencję
    }
}
